import{_ as e}from"./chunks/btn_vyjadreni.Dg2MFdOG.js";import{_ as n,o as i,c as o,aa as a}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/tickets/en_kanban.png",r="/buildary-help-preview/media/en/tickets/en_kanban2_prace_s_ukoly.png",c="/buildary-help-preview/media/cs/tickets/btn_threedot.png",u=JSON.parse('{"title":"Ticket Kanban","description":"","frontmatter":{"title":"Ticket Kanban","wiki":"en:tickets:kanban"},"headers":[],"relativePath":"en/tickets/kanban.md","filePath":"en/tickets/kanban.md","lastUpdated":1794388980000}'),h={name:"en/tickets/kanban.md"};function g(l,t,d,p,m,k){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ticket-kanban" tabindex="-1">Ticket Kanban <a class="header-anchor" href="#ticket-kanban" aria-label="Permalink to &quot;Ticket Kanban&quot;">​</a></h1><p>For better orientation and more convenient work with tickets, users can <strong>switch</strong> from the grid to the Kanban view. Some operations are significantly easier in this view. It does not matter whether the user uses the <strong>view switcher in the top right corner of the Ticket List</strong> or clicks <strong>Ticket Kanban in the left panel</strong>. In both cases, they are taken to a page with tickets arranged in the Kanban system, while retaining the ticket filter settings from the top row.</p><figure class="shot" style="--w:620px;"><img src="'+s+'" alt="Ticket Kanban" width="600" loading="lazy"></figure><p><strong>Kanban</strong> is a clear <strong>arrangement of tickets into columns according to ticket status</strong>, making it exceptionally easy to work with.</p><p><strong>The major advantage of Kanban is working with tickets</strong>, which can be easily <strong>moved between columns</strong>, changing the ticket status without having to open the ticket for editing. Simply &quot;grab&quot; a ticket with the mouse and move it to the desired column (indicated by the arrow in the image below). Tickets can only be moved between columns with a logical status progression, and this action can only be performed by a user with the appropriate permission.</p><p><strong><strong>The image below summarizes the available options for working in Kanban:</strong></strong></p><figure class="shot" style="--w:720px;"><img src="'+r+'" alt="Working with Tickets in Kanban" width="700" loading="lazy"></figure><p>Above the columns, there is a <strong>Column Selection</strong> option. A maximum of <strong>8 columns</strong> can be displayed: Draft / Not Started / In Progress / On Hold / Completed / Postponed / Rejected / Approved.</p><p>Next to this option, there is a switch between the grid and Kanban views.</p><p><strong>Some column headers</strong> contain a <strong>+</strong> button, which creates a <strong>new ticket</strong> with its status automatically set according to the respective column.</p><p><strong>The first row of each ticket contains 3 active elements:</strong></p><ul><li>clicking the <strong>Ticket Subject</strong> opens <strong>Ticket Details</strong>, where the ticket can be edited, added to the discussion, etc.</li><li>the <img src="'+e+'" alt="Statement Icon" width="20" data-no-zoom loading="lazy"> icon indicates that a <strong>Statement</strong> exists for the ticket and opens the <strong>entire Statement thread</strong> with its associated records.</li><li>the <img src="'+c+'" alt="Vertical Three-Dot Menu" width="20" data-no-zoom loading="lazy"> icon provides the option to <strong>export the ticket to PDF</strong> or <strong>delete the ticket</strong></li></ul>',12)])])}const _=n(h,[["render",g]]);export{u as __pageData,_ as default};
